CREATE TABLE IF NOT EXISTS payment_product(product_id varchar(128) PRIMARY KEY,amount decimal(18,2) NOT NULL,currency char(3) NOT NULL,credit decimal(18,2) NOT NULL,published boolean NOT NULL,CHECK(amount>0 AND credit>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS payment_order(order_id varchar(128) PRIMARY KEY,user_id varchar(128) NOT NULL,request_id varchar(128) NOT NULL,request_hash char(64) NOT NULL,state varchar(32) NOT NULL,provider_create_status varchar(32) NOT NULL,recovery_status varchar(32) NOT NULL DEFAULT 'ACTIVE',version bigint NOT NULL DEFAULT 0,snapshot json NOT NULL,last_progress_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),paid_at datetime(6),delivered_at datetime(6),UNIQUE KEY request_identity(user_id,request_id),INDEX recovery_scan(recovery_status,state,last_progress_at,order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS provider_inbox(provider varchar(32) NOT NULL,account varchar(128) NOT NULL,environment varchar(32) NOT NULL,event_id varchar(128) NOT NULL,canonical_hash char(64) NOT NULL,payload json NOT NULL,state varchar(16) NOT NULL DEFAULT 'PENDING',lease_token varchar(128),lease_until datetime(6),next_attempt_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(provider,account,environment,event_id),INDEX pending(state,next_attempt_at,event_id),INDEX expired(state,lease_until,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS provider_payment_fact(provider varchar(32) NOT NULL,account varchar(128) NOT NULL,environment varchar(32) NOT NULL,transaction_id varchar(128) NOT NULL,order_id varchar(128) NOT NULL,user_id varchar(128) NOT NULL,amount decimal(18,2) NOT NULL,currency char(3) NOT NULL,reversed boolean NOT NULL DEFAULT false,paid boolean NOT NULL DEFAULT false,PRIMARY KEY(provider,account,environment,transaction_id),INDEX by_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS payment_review(evidence_hash char(64) PRIMARY KEY,order_id varchar(128) NOT NULL,reason varchar(1024) NOT NULL,payload json NOT NULL,created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX by_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sandbox_payment(merchant_order_id varchar(128) PRIMARY KEY,amount decimal(18,2) NOT NULL,currency char(3) NOT NULL,status varchar(16) NOT NULL DEFAULT 'CREATED',fact json) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS payment_scan_cursor(order_id varchar(128) PRIMARY KEY,checked_at datetime(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS payment_stage(order_id varchar(128) NOT NULL,stage varchar(32) NOT NULL,recorded_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(order_id,stage)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
